use super::{admission::{Budget,Payment,Review,Evidence,Denial},admission_tests::Fixture,authority::{Authority,Operation,Failure},model::*,store::nonce,lease_controller::{Controller,Owned,Validity}};
use crate::{chat::Chat,settings::Settings};
use std::{sync::Arc,fs};
use serde_json::{json,Value};
pub(super)fn evidence(goal:&Record,now:u64)->Evidence{
 let b=crate::pet_config::blueprint(&goal.spec.owner.pet_id).unwrap();
 let mut d=crate::pet_capabilities::Descriptor{schema_version:1,pet_id:goal.spec.owner.pet_id.clone(),kind:if b.service{crate::pet_capabilities::Kind::Service}else{crate::pet_capabilities::Kind::Llm},name:"Native fixture".into(),lifecycle:crate::pet_capabilities::Lifecycle::Active,binding:crate::pet_capabilities::Binding{engine_binding:None,provider:Some(goal.spec.owner.provider.clone()),adapter:b.runtime.adapter.map(|a|a.key()),model:None,profile:None},revision:"fixture".into(),observed_at:None,configuration_available:true,capabilities:vec![],concurrency:crate::pet_capabilities::Concurrency{scope:None,max_active:None}};d.binding.model=None;d.binding.engine_binding=None;d.capabilities.clear();
 d.kind=if crate::pet_config::blueprint(&goal.spec.owner.pet_id).unwrap().service{crate::pet_capabilities::Kind::Service}else{crate::pet_capabilities::Kind::Llm};
 Evidence::observe_deterministic(goal,&d,"a".repeat(64),now).unwrap()
}
fn budget(now:u64)->Budget{Budget{deadline_at:now+120_000,max_model_calls:0,max_tool_calls:2,max_output_bytes:32768,max_tokens:None,max_cost_micros:None,payment:Payment::RuntimeOnly}}
pub(super)fn draft(f:&Fixture,provider:&str)->Record{draft_with(f,provider,vec!["Delivery is data, not recipient execution".into()],1)}
pub(super)fn draft_with(f:&Fixture,provider:&str,criteria:Vec<String>,count:usize)->Record{
 let b=crate::pet_config::blueprints().find(|b|b.routing.chat.as_deref()==Some(provider)||b.routing.task_provider.as_deref()==Some(provider)).unwrap().clone();let adapter=b.runtime.adapter.map(|a|a.key()).unwrap_or(provider);
 let g=f.store().create(Spec{received_from:None,restored_from:None,request_id:nonce().unwrap(),owner:Owner{pet_id:b.id.clone(),provider:provider.into(),adapter:adapter.into(),model_hint:None},context:Context::Unbound,intent:"Native complete intent".into(),criteria},100_000).unwrap().record;
 let main=Chat::persistent(f.path.join("preparation.json"));let(binding,c)=super::context::prepare(&f.path.join("contexts"),&g,&main,PreparationMode::Dedicated,"native-context").unwrap();drop(c);let g=f.store().mutate(&g.id,&g.spec.owner.pet_id,&g.revision,"native-context".into(),Action::BindContext{binding},100_001).unwrap().record;let at=crate::assistant_memory::now();let store=f.store();let g=store.mutate(&g.id,&g.spec.owner.pet_id,&g.revision,"native-task".into(),Action::ProposeTask{description:"Literal local peer data".into()},at).unwrap().record;
 let to=if g.spec.owner.pet_id=="ai_ollama"{"integration_spotify"}else{"ai_ollama"};
 store.mutate(&g.id,&g.spec.owner.pet_id,&g.revision,"native-plan".into(),Action::ProposePlan{task_id:g.tasks[0].id.clone(),steps:(0..count).map(|i|StepInput{description:format!("Local native message {i}"),postcondition:"Received data, recipient execution not authorized".into(),operation:Some(super::plans::OperationProposal{operation_id:"pet.message".into(),version:1,arguments:json!({"toPetId":to,"kind":"message","text":format!("Untrusted literal {i}, no new policy or data access"),"expiresAt":at+60_000})})}).collect()},at).unwrap().record
}
pub(super)fn queued(f:&Fixture,a:&Authority,g:&Record)->Record{let now=crate::assistant_memory::now();let review=Review::prepare_deterministic(g,evidence(g,now),budget(now),"native-only-admission".into(),nonce().unwrap(),now).unwrap();assert_eq!(review.proposal().operation,"goalDeterministic");assert!(review.proposal().resolved_model.is_empty());let approved=review.approve(g,evidence(g,now),now).unwrap();let cert=a.certify(&approved,g,now).unwrap();f.store().enqueue_certified(&cert,now).unwrap().record}
pub(super)fn owned(f:&Fixture,a:&Authority,g:&Record,chat:&Chat)->(Record,Owned){let now=crate::assistant_memory::now();let p=Controller::new().unwrap().prepare(g,&f.path.join("authority"),&f.path.join("contexts"),chat,&evidence(g,now),format!("native-claim-{}",nonce().unwrap()),now,Arc::new(|_,_,_|Validity::Current)).unwrap();let(r,o)=p.claim(&f.store(),a,&evidence(g,now),now).unwrap();(r.record,o.unwrap())}
fn body(f:&Fixture,g:&Record)->Value{serde_json::from_slice::<Value>(&fs::read(f.path.join("authority").join(format!("{}.json",g.admissions[0].spec.decision_id))).unwrap()).unwrap()["body"].clone()}
#[test]fn deterministic_runtime_all_supported_factory_owners_admit_claim_and_send_without_any_model_evidence(){
 for provider in ["codex","copilot","antigravity","ollama","lmstudio","openai","integration_spotify"]{
  let f=Fixture::new();let a=Authority::ensure(&f.path.join("authority")).unwrap();let g=draft(&f,provider);let q=queued(&f,&a,&g);assert_eq!(q.schema_version,16);assert_eq!(q.admissions[0].spec.schema_version,4);assert_eq!(q.admissions[0].proof.as_ref().unwrap().operation,Operation::GoalDeterministic);assert_eq!(q.admissions[0].proof.as_ref().unwrap().schema_version,3);
  let chat=Chat::persistent(f.path.join("main.json"));let(g,o)=owned(&f,&a,&q,&chat);assert_eq!(o.lease().schema_version,2);assert!(o.lease().model.is_empty());assert!(o.server_projection(&Settings::default()).is_err());let row=&g.admissions[0];
  let mut config=crate::pet_config::defaults();if provider=="lmstudio"{config.pets.get_mut("ai_lmstudio").unwrap().provider="lmstudio".into();}let mut settings=Settings::default();settings.active_integrations=vec!["ai_ollama".into(),"integration_spotify".into()];
  let args=super::messages::Arguments::parse(&g.plans[0].steps[0].operation.as_ref().unwrap().arguments).unwrap();let target=Arc::new(super::messages::Target::capture(&config,&settings,&args.to_pet_id).unwrap());let now=crate::assistant_memory::now();let review=o.review_message(&g,&g.plans[0].id,&g.plans[0].steps[0].id,"native-direct-message".into(),target,now).unwrap();let approval=review.approve(&o,&g,&config,&settings,now,Arc::new(||true)).unwrap();let receipt=o.send_message(&g,&approval,now,||Ok((config.clone(),settings.clone()))).unwrap();assert_eq!(receipt.envelope().origin.pet_id,g.spec.owner.pet_id);assert!(!receipt.envelope().provider_use_authorized);
  let saved=body(&f,&g);assert_eq!(saved["schemaVersion"],10);assert_eq!(saved["budgetUsage"]["attempts"].as_array().unwrap().len(),1);assert_eq!(saved["budgetUsage"]["attempts"][0]["kind"],"tool");let bytes=fs::read(f.path.join("authority").join(format!("{}.json",row.spec.decision_id))).unwrap();assert_eq!(a.message_ack(&row.spec,row.proof.as_ref().unwrap(),&receipt.scope).unwrap().unwrap(),receipt);assert_eq!(fs::read(f.path.join("authority").join(format!("{}.json",row.spec.decision_id))).unwrap(),bytes);assert!(!f.path.join("main.json").exists());
 }
}
#[test]fn deterministic_runtime_zero_model_calls_are_not_a_legacy_permission_or_a_model_dispatch_budget(){
 let f=Fixture::new();let a=Authority::ensure(&f.path.join("authority")).unwrap();let g=draft(&f,"ollama");let now=crate::assistant_memory::now();assert!(!budget(now).valid(now));let legacy=super::admission_tests::evidence(&g,now);assert_eq!(Review::prepare(&g,legacy,budget(now),"cannot-downgrade".into(),nonce().unwrap(),now).err(),Some(Denial::Budget));
 let q=queued(&f,&a,&g);let(g,o)=owned(&f,&a,&q,&Chat::persistent(f.path.join("main.json")));let row=&g.admissions[0];let attempt=super::effect_budget::Attempt{id:nonce().unwrap(),request_id:"never-model".into(),input_hash:"a".repeat(64),kind:super::effect_budget::Kind::Model,output_reserved:100,phase:super::effect_budget::Phase::Reserved,accepted_output:None,reserved_at:now,started_at:None,finished_at:None};let before=body(&f,&g);assert_eq!(a.reserve_attempt(&row.spec,row.proof.as_ref().unwrap(),o.lease(),&attempt,crate::assistant_memory::now()).err(),Some(Failure::Invalid));assert_eq!(body(&f,&g),before);
 let mut wrong=row.spec.clone();wrong.schema_version=2;assert!(!wrong.binding_format());let mut wrong=row.spec.clone();wrong.resolved_model="invented-runtime-model".into();assert!(!wrong.binding_format());
}
#[test]fn deterministic_runtime_independent_actor_never_reserves_or_releases_another_pets_inference_hold(){
 let f=Fixture::new();let mut config=crate::pet_config::defaults();config.version=2;for(id,rev)in[("ai_ollama","a"),("ai_lmstudio","b")]{let p=config.pets.get_mut(id).unwrap();p.inference=Some(crate::pet_inference::Choice{schema_version:1,backend:crate::pet_inference::Backend::Ollama,endpoint:"http://127.0.0.1:1".into(),model:"unavailable-free-fixture".into(),credential:crate::pet_inference::CredentialReference::None});p.inference_revision=Some(rev.repeat(32));}let path=f.path.join("pets.json");fs::write(&path,serde_json::to_vec(&config).unwrap()).unwrap();let resources=Arc::new(crate::pet_resources::Coordinator::with_fixture(Arc::new(std::sync::Mutex::new(Settings::default())),path));let physical=resources.acquire("lmstudio",Arc::default(),None).unwrap();assert!(resources.acquire_goal("ollama",Arc::default(),None).is_err());
 let a=Authority::ensure(&f.path.join("authority")).unwrap();let g=draft(&f,"ollama");let q=queued(&f,&a,&g);let main=Chat::persistent(f.path.join("main.json")).with_runtime_resources(resources.clone());let(g,o)=owned(&f,&a,&q,&main);assert!(physical.current()&&o.policy_current(crate::assistant_memory::now()));assert!(resources.acquire_goal("lmstudio",Arc::default(),None).is_err());let drained=o.drain(super::leases::DrainOutcome::Confirmed).unwrap();f.store().drain_owned(&a,&drained,crate::assistant_memory::now()).unwrap();assert!(physical.current());assert_eq!(body(&f,&g)["schemaVersion"],13);
}
#[test]fn deterministic_runtime_lost_admission_ack_reuses_original_mode_budget_and_authority(){
 for fault in [super::store::Fault::BeforePublish,super::store::Fault::AfterPublish]{let f=Fixture::new();let a=Authority::ensure(&f.path.join("authority")).unwrap();let g=draft(&f,"copilot");let now=crate::assistant_memory::now();let approved=Review::prepare_deterministic(&g,evidence(&g,now),budget(now),"native-ack".into(),nonce().unwrap(),now).unwrap().approve(&g,evidence(&g,now),now).unwrap();let cert=a.certify(&approved,&g,now).unwrap();let mut store=f.store();store.fault=fault;let _=store.enqueue_certified(&cert,now);store.fault=super::store::Fault::None;let retry=if matches!(fault,super::store::Fault::BeforePublish){assert!(store.enqueue_certified(&cert,now+500_000).is_err());now+1}else{now+500_000};let again=store.enqueue_certified(&cert,retry).unwrap();assert_eq!(again.record.admissions.len(),1);assert_eq!(again.record.admissions[0].spec.budget,approved.spec().budget);assert_eq!(again.record.schema_version,16);assert_eq!(body(&f,&again.record)["operation"],"goalDeterministic");}
}
#[test]fn deterministic_runtime_unused_signed_native_authority_retires_without_admitting_or_refunding_work(){
 let f=Fixture::new();let path=f.path.join("authority");let a=Authority::ensure(&path).unwrap();let g=draft(&f,"openai");let now=crate::assistant_memory::now();let approved=Review::prepare_deterministic(&g,evidence(&g,now),budget(now),"native-orphan".into(),nonce().unwrap(),now).unwrap().approve(&g,evidence(&g,now),now).unwrap();let decision=approved.spec().decision_id.clone();a.certify(&approved,&g,now).unwrap();let store=super::store::Store::existing_verified(&f.path.join("goals"),&path).unwrap().unwrap();
 let review=match store.prepare_retirement(&path,&g.id,&g.spec.owner.pet_id,&g.revision,&decision,"retire-native-orphan".into(),now+1).unwrap(){super::retirement_controller::Prepared::Review(r)=>r,_=>panic!("new review required")};assert_eq!(review.proposal().original_operation,"goalDeterministic");let choice=review.decide(now+2).unwrap();let mut retired=review.approve(choice);let receipt=retired.confirm(&store,now+3).unwrap();assert_eq!(receipt.reference.schema_version,2);assert_eq!(receipt.reference.source_grant_schema,10);assert!(!receipt.execution_available&&!receipt.new_admission_created);assert_eq!(super::model::fingerprint(&receipt.record).unwrap(),super::model::fingerprint(&g).unwrap());let saved:Value=serde_json::from_slice(&fs::read(path.join(format!("{decision}.json"))).unwrap()).unwrap();assert_eq!(saved["body"]["schemaVersion"],10);assert_eq!(saved["body"]["phase"],"revoked");assert!(saved["body"].get("lease").is_none());
 let before=super::reconciliation_tests::inventory(&f.path);retired.acknowledged().receipt(&store).unwrap();assert_eq!(super::reconciliation_tests::inventory(&f.path),before);let history=store.history(&path,&g.id,&g.spec.owner.pet_id,&g.revision,now+4).unwrap();assert!(history.accounting_complete);assert_eq!(history.cumulative_charge.unwrap().model_calls,0);
}
#[test]fn deterministic_runtime_reopen_keeps_mode_and_revoked_grant_cannot_be_replayed_as_inference_or_reclaimed(){
 let f=Fixture::new();let path=f.path.join("authority");let a=Authority::ensure(&path).unwrap();let q=queued(&f,&a,&draft(&f,"ollama"));let store=super::store::Store::existing_verified(&f.path.join("goals"),&path).unwrap().unwrap();let g=store.read(&q.id,&q.spec.owner.pet_id).unwrap();assert_eq!(super::model::fingerprint(&g).unwrap(),super::model::fingerprint(&q).unwrap());let row=&g.admissions[0];let now=crate::assistant_memory::now();a.revoke(&row.spec,row.proof.as_ref().unwrap(),now).unwrap();assert_eq!(body(&f,&g)["schemaVersion"],10);assert_eq!(body(&f,&g)["phase"],"revoked");let before=super::reconciliation_tests::inventory(&f.path);
 let main=Chat::persistent(f.path.join("main.json"));assert!(Controller::new().unwrap().prepare(&g,&path,&f.path.join("contexts"),&main,&evidence(&g,now),"cannot-reclaim".into(),now,Arc::new(|_,_,_|Validity::Current)).is_err());assert_eq!(super::reconciliation_tests::inventory(&f.path),before);assert_eq!(store.read(&g.id,&g.spec.owner.pet_id).unwrap().admissions[0].spec.budget.max_model_calls,0);
 let mut wrong=row.proof.clone().unwrap();wrong.operation=Operation::ConversationRespond;wrong.schema_version=1;assert!(!wrong.matches(&row.spec));
}
